import React, { useEffect, useRef } from 'react';

interface FlowLineProps {
  from: HTMLElement | null;
  to: HTMLElement | null;
  color?: string;
  duration?: number;
  onComplete?: () => void;
}

export const FlowLine: React.FC<FlowLineProps> = ({
  from,
  to,
  color = 'var(--retro-primary)',
  duration = 1000,
  onComplete
}) => {
  const svgRef = useRef<SVGSVGElement>(null);
  const pathRef = useRef<SVGPathElement>(null);

  useEffect(() => {
    if (!from || !to || !svgRef.current || !pathRef.current) return;

    const fromRect = from.getBoundingClientRect();
    const toRect = to.getBoundingClientRect();

    const x1 = fromRect.left + fromRect.width / 2;
    const y1 = fromRect.top + fromRect.height / 2;
    const x2 = toRect.left + toRect.width / 2;
    const y2 = toRect.top + toRect.height / 2;

    // Calculate bezier control point for smooth curve
    const cx = (x1 + x2) / 2;
    const cy = Math.min(y1, y2) - 50; // Curve upward

    const pathD = `M ${x1},${y1} Q ${cx},${cy} ${x2},${y2}`;
    pathRef.current.setAttribute('d', pathD);

    const pathLength = pathRef.current.getTotalLength();
    pathRef.current.style.strokeDasharray = `${pathLength}`;
    pathRef.current.style.strokeDashoffset = `${pathLength}`;

    // Trigger animation
    requestAnimationFrame(() => {
      if (pathRef.current) {
        pathRef.current.style.transition = `stroke-dashoffset ${duration}ms ease-out`;
        pathRef.current.style.strokeDashoffset = '0';
      }
    });

    const timer = setTimeout(() => {
      onComplete?.();
    }, duration);

    return () => clearTimeout(timer);
  }, [from, to, duration, onComplete]);

  return (
    <svg
      ref={svgRef}
      className="flow-line-overlay"
      style={{
        position: 'fixed',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        pointerEvents: 'none',
        zIndex: 1000
      }}
    >
      <path
        ref={pathRef}
        stroke={color}
        strokeWidth="2"
        fill="none"
        filter="drop-shadow(0 0 4px currentColor)"
        opacity="0.8"
      />
    </svg>
  );
};

