export class Particle {
  x: number = 0;
  y: number = 0;
  progress: number = 0;
  speed: number;
  size: number;
  color: string;
  alpha: number = 1;
  path: { x: number; y: number }[];
  active: boolean = false;

  constructor() {
    this.speed = 0.02 + Math.random() * 0.02;
    this.size = 2 + Math.random() * 2;
    this.color = 'rgba(140, 184, 17, 1)';
    this.path = [];
  }

  init(path: { x: number; y: number }[]) {
    this.path = path;
    this.progress = 0;
    this.active = true;
    this.alpha = 0;
  }

  update() {
    if (!this.active || this.path.length === 0) return;

    this.progress += this.speed;

    // Fade in/out
    if (this.progress < 0.2) {
      this.alpha = this.progress / 0.2;
    } else if (this.progress > 0.8) {
      this.alpha = (1 - this.progress) / 0.2;
    } else {
      this.alpha = 1;
    }

    if (this.progress >= 1) {
      this.active = false;
      return;
    }

    const index = Math.floor(this.progress * (this.path.length - 1));
    const nextIndex = Math.min(index + 1, this.path.length - 1);
    const segmentProgress = (this.progress * (this.path.length - 1)) % 1;

    // Interpolate position
    this.x = this.path[index].x + (this.path[nextIndex].x - this.path[index].x) * segmentProgress;
    this.y = this.path[index].y + (this.path[nextIndex].y - this.path[index].y) * segmentProgress;
  }

  draw(ctx: CanvasRenderingContext2D) {
    if (!this.active || this.alpha <= 0) return;

    ctx.save();
    ctx.globalAlpha = this.alpha;
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x - this.size / 2, this.y - this.size / 2, this.size, this.size);
    ctx.restore();
  }
}

export class ParticleSystem {
  particles: Particle[];
  canvas: HTMLCanvasElement;
  ctx: CanvasRenderingContext2D;
  animationId: number | null = null;

  constructor(canvas: HTMLCanvasElement, poolSize: number = 50) {
    this.canvas = canvas;
    this.ctx = canvas.getContext('2d')!;
    this.particles = Array.from({ length: poolSize }, () => new Particle());
  }

  spawnParticles(path: { x: number; y: number }[], count: number = 5) {
    let spawned = 0;
    for (const particle of this.particles) {
      if (!particle.active && spawned < count) {
        particle.init(path);
        spawned++;
      }
      if (spawned >= count) break;
    }
  }

  animate = () => {
    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);

    for (const particle of this.particles) {
      particle.update();
      particle.draw(this.ctx);
    }

    this.animationId = requestAnimationFrame(this.animate);
  };

  start() {
    if (!this.animationId) {
      this.animate();
    }
  }

  stop() {
    if (this.animationId) {
      cancelAnimationFrame(this.animationId);
      this.animationId = null;
    }
  }

  pathFromSVG(svgPath: SVGPathElement): { x: number; y: number }[] {
    const points: { x: number; y: number }[] = [];
    const length = svgPath.getTotalLength();
    const samples = 100;

    for (let i = 0; i <= samples; i++) {
      const point = svgPath.getPointAtLength((i / samples) * length);
      points.push({ x: point.x, y: point.y });
    }

    return points;
  }
}

