/* Visual Feedback Animations */

/* Pulse Glow - AI Processing */
@keyframes pulse-glow {
  0%, 100% {
    box-shadow: 0 0 5px var(--retro-primary),
                inset 0 0 5px var(--retro-primary);
  }
  50% {
    box-shadow: 0 0 20px var(--retro-primary),
                0 0 30px var(--retro-accent-yellow),
                inset 0 0 10px var(--retro-primary);
  }
}

.ai-processing {
  animation: pulse-glow 1.5s ease-in-out infinite;
  position: relative;
}

/* Success Flash */
@keyframes success-flash {
  0% { background-color: transparent; }
  50% { background-color: rgba(140, 184, 17, 0.3); }
  100% { background-color: transparent; }
}

.success-feedback {
  animation: success-flash 0.5s ease-out;
}

/* Screen Flash Overlay */
@keyframes screen-flash {
  0% {
    opacity: 0;
    background: var(--retro-accent-yellow);
  }
  30% {
    opacity: 0.8;
  }
  100% {
    opacity: 0;
  }
}

.screen-flash-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 9999;
  animation: screen-flash 0.4s ease-out;
}

/* Shake Error */
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  10%, 30%, 50%, 70%, 90% { transform: translateX(-4px); }
  20%, 40%, 60%, 80% { transform: translateX(4px); }
}

.error-shake {
  animation: shake 0.4s cubic-bezier(.36,.07,.19,.97);
  border-color: var(--palm-red) !important;
}

/* Retro-style stepped pulse */
@keyframes retro-pulse {
  0% { opacity: 1; }
  50% { opacity: 0.6; }
  100% { opacity: 1; }
}

.retro-pulse {
  animation: retro-pulse 1s steps(5) infinite;
}

/* CRT Scanline Sweep */
@keyframes scanline-sweep {
  0% { transform: translateY(-100%); }
  100% { transform: translateY(100%); }
}

.scanline-effect::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(to bottom,
    transparent,
    rgba(255, 255, 255, 0.3),
    transparent
  );
  animation: scanline-sweep 2s linear infinite;
  pointer-events: none;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }

  .flow-line {
    stroke-dashoffset: 0 !important;
    animation: none !important;
  }

  .particle-canvas {
    display: none !important;
  }
}

