import { useState, useRef, useEffect } from 'react';
import { FlowLine } from '@/components/ui/FlowLine';
import { ParticleSystem } from '@/lib/particles';

export default function HomePage() {
  const [showFlow, setShowFlow] = useState(false);
  const sourceRef = useRef<HTMLDivElement>(null);
  const targetRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const particleSystemRef = useRef<ParticleSystem | null>(null);

  useEffect(() => {
    if (canvasRef.current && !particleSystemRef.current) {
      particleSystemRef.current = new ParticleSystem(canvasRef.current);
      particleSystemRef.current.start();
    }

    return () => {
      particleSystemRef.current?.stop();
    };
  }, []);

  const handleConversion = async () => {
    // Show flow line
    setShowFlow(true);

    // Add success feedback class
    targetRef.current?.classList.add('success-feedback');

    // Trigger screen flash
    const flashDiv = document.createElement('div');
    flashDiv.className = 'screen-flash-overlay';
    document.body.appendChild(flashDiv);
    setTimeout(() => flashDiv.remove(), 400);

    // Spawn particles after flow line completes
    setTimeout(() => {
      if (particleSystemRef.current && sourceRef.current && targetRef.current) {
        const path = calculatePathPoints(sourceRef.current, targetRef.current);
        particleSystemRef.current.spawnParticles(path, 10);
      }
    }, 500);

    // Cleanup
    setTimeout(() => {
      setShowFlow(false);
      targetRef.current?.classList.remove('success-feedback');
    }, 1500);
  };

  return (
    <div className="relative">
      <div ref={sourceRef} className="retro-card">Source Item</div>
      <div ref={targetRef} className="retro-card mt-4">Target Item</div>

      <button onClick={handleConversion} className="retro-button-primary mt-4">
        Convert
      </button>

      {showFlow && (
        <FlowLine
          from={sourceRef.current}
          to={targetRef.current}
          onComplete={() => console.log('Flow complete')}
        />
      )}

      <canvas
        ref={canvasRef}
        className="particle-canvas"
        style={{
          position: 'fixed',
          top: 0,
          left: 0,
          width: '100%',
          height: '100%',
          pointerEvents: 'none',
          zIndex: 999
        }}
      />
    </div>
  );
}

function calculatePathPoints(
  from: HTMLElement,
  to: HTMLElement
): { x: number; y: number }[] {
  const fromRect = from.getBoundingClientRect();
  const toRect = to.getBoundingClientRect();
  const points: { x: number; y: number }[] = [];

  const x1 = fromRect.left + fromRect.width / 2;
  const y1 = fromRect.top + fromRect.height / 2;
  const x2 = toRect.left + toRect.width / 2;
  const y2 = toRect.top + toRect.height / 2;

  // Generate bezier curve points
  const steps = 100;
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const cx = (x1 + x2) / 2;
    const cy = Math.min(y1, y2) - 50;

    // Quadratic bezier formula
    const x = (1 - t) * (1 - t) * x1 + 2 * (1 - t) * t * cx + t * t * x2;
    const y = (1 - t) * (1 - t) * y1 + 2 * (1 - t) * t * cy + t * t * y2;

    points.push({ x, y });
  }

  return points;
}
